def maxDepth(root):
    if root is None:
        return 0
    return 1 + max(maxDepth(root.left), maxDepth(root.right))

def targetSum(root, targetSum):
    if root is None:
        return False
    if root.val == targetSum:
        return True
    return targetSum(root.left, targetSum - root.val) or targetSum(root.right, targetSum - root.val)
