std::vector<int> kthSmallestPath(std::vector<std::vector<int>>& grid, int k) {
    std::vector<int> result;
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<int>> visited(m, std::vector<int>(n, 0));
    std::queue<std::pair<int, int>> q;
    q.push({0, 0});
    visited[0][0] = 1;
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        if (x == m - 1 && y == n - 1) {
            result.push_back(grid[x][y]);
            break;
        }
        if (x + 1 < m && !visited[x + 1][y]) {
            q.push({x + 1, y});
            visited[x + 1][y] = 1;
        }
        if (y + 1 < n && !visited[x][y + 1]) {
            q.push({x, y + 1});
            visited[x][y + 1] = 1;
        }
    }
    return result;
}
