        if (!dict.contains(prefix)) continue;
        String suffix = s.substring(i);
        List<String> temp = helper(suffix, dict, memo);
        for (String t : temp) {
            res.add(prefix + " " + t);
        }
    }

    memo.put(s, res);
    return res;
}
