def subset_sum(nums):
    n = len(nums)
    dp = [[False] * (sum(nums) + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for i in range(1, n + 1):
        for j in range(1, sum(nums) + 1):
            if j >= nums[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
    return dp[n][sum(nums)]

