class MinStack:

    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, val: int):
        self.stack.append(val)
        if not self.min_stack or val <= self.min_stack[-1]:
            self.min_stack.append(val)

    def pop(self):
        if self.stack[-1] == self.min_stack[-1]:
            self.min_stack.pop()
        self.stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        return self.min_stack[-1]

    def getKthSmallest(self, nums: List[int], k: int) -> int:
        self.stack = nums
        self.min_stack = []
        for i in range(k):
            if not self.min_stack or self.stack[i] <= self.min_stack[-1]:
                self.min_stack.append(self.stack[i])
        return self.min_stack[-1]
