class TreeNode:
    def __init__(self, left=None, right=None):
        self.left = left
        self.right = right

def count_nodes(root):
    if not root:
        return 0
    ld = rd = 0
    l = r = root

    while l:
        l = l.left
        ld += 1

    while r:
        r = r.right
        rd += 1

    if ld == rd:
        return (1 << ld) - 1
    return 1 + count_nodes(root.left) + count_nodes(root.right)

def get_sum(root, target):
    if not root:
        return 0

    left_sum = get_sum(root.left, target)
    right_sum = get_sum(root.right, target)

    if left_sum + right_sum == target:
        return 1 + left_sum + right_sum
    elif left_sum + right_sum > target:
        return get_sum(root.left, target - (left_sum + right_sum))
    else:
        return get_sum(root.right, target - (left_sum + right_sum))

