            String key = deltaX + "_" + deltaY;
            slopeMap.put(key, slopeMap.getOrDefault(key, 0) + 1);
            localMax = Math.max(localMax, slopeMap.get(key));
        }
        maxCount = Math.max(maxCount, localMax + duplicates + 1);
    }

    return maxCount;
}

private int gcd(int a, int b) {
    if(b == 0) return a;
    return gcd(b, a % b);
}
