def encode(strs):
    encoded_string = ""
    for s in strs:
        encoded_string += str(len(s)) + "#" + s
    return encoded_string

def decode(s):
    strs = []
    i = 0
    while i < len(s):
        delimiter_pos = s.find('#', i)
        length = int(s[i:delimiter_pos])
        strs.append(s[delimiter_pos + 1:delimiter_pos + 1 + length])
        i = delimiter_pos + 1 + length
    return strs

def count_unique_chars(chars):
    unique_chars = set()
    for char in chars:
        if char not in unique_chars:
            unique_chars.add(char)
    return len(unique_chars)

def encode_and_count_unique_chars(strs):
    encoded_string = encode(strs)
    count = count_unique_chars(encoded_string)
    return count, encoded_string

def decode_and_count_unique_chars(s):
    decoded_strs = decode(s)
    count = count_unique_chars(decoded_strs)
    return count, decoded_strs

