class NestedInteger {
    public int integer;
    public List<NestedInteger> list;

    public NestedInteger(int integer) {
        this.integer = integer;
    }

    public NestedInteger(List<NestedInteger> list) {
        this.list = list;
    }

    public boolean isInteger() {
        return this.integer != null;
    }

    public int getInteger() {
        return this.integer;
