public class Solution {
    public int depthSumInverse(List<NestedInteger> nestedList) {
        NestedIterator it = new NestedIterator(nestedList);
        int sum = 0;
        while (it.hasNext()) {
            sum += it.next() * (it.hasNext() ? it.next() : 1);
        }
        return sum;
    }
}
